//! `LocOpe_DPrism` (`ModelingAlgorithms/TKFeat/LocOpe/LocOpe_DPrism`).
//!
//! A "draft prism" local feature: a face of the base shape is swept along a
//! three-segment profile built in the `XOY`-normalised frame (`Height1` above,
//! `Height2` below, both tilted by `Angle`), the sweep being `BRepFill_Evolved`
//! (`cxx:110` / `cxx:389`). The two end caps of the sweep are then recovered
//! from the faces generated by the first / the last profile edge and the whole
//! feature is assembled with `LocOpe_BuildShape`.
//!
//! Module table (`ModelingAlgorithms/TKFeat/LocOpe/LocOpe_DPrism`):
//!
//! | OCCT | Rust |
//! |---|---|
//! | `hxx:38-84` (members) | [`DPrism`] |
//! | ctors (`cxx:61-360`, `cxx:365-552`) | [`DPrism::with_two_heights`] / [`DPrism::with_height`] |
//! | profile wire (`cxx:70-110`, `cxx:366-390`) | [`profiles`] |
//! | `Perform` bodies (`cxx:112-359`, `cxx:391-551`) | [`perform`] |
//! | `IsDone` / `Shape` / `Spine` / `Profile` / `FirstShape` / `LastShape` / `Shapes` (`cxx:556-618`) | the accessors below |
//! | `Curves` (`cxx:620-690`) / `BarycCurve` (`cxx:694-753`) | [`sections`] |
//!
//! Container mapping: `myMap` (`NCollection_DataMap<TopoDS_Shape,
//! NCollection_List<TopoDS_Shape>>`) is [`ShapeValueMap<Vec<TopoShape>>`]. The
//! reference's `myCurvs` (`hxx:81`) is written nowhere in the `.cxx` (neither
//! ctor nor `Curves` touches it), so it has no counterpart here.
//!
//! Deviations, all forced by the language or already recorded for this tree:
//! - `myRes` / `myProfile` / the three profile edges have no null state, so
//!   they are `Option<...>`; `Shape()` answers `None` where OCCT raises
//!   `StdFail_NotDone`, and `Profile()` answers `None` where OCCT would hand
//!   back a null wire (a degenerate profile, `cxx:82` `BRepLib_MakeEdge` on two
//!   identical points).
//! - `BRepLib_MakeVertex` uses `BRepLib::Precision()` (`cxx:76` `:79` `:93`
//!   `:106` `:374` `:383` `:385`), which the tree spells
//!   `precision::CONFUSION`.
//! - The reference keeps building the profile even when `BRepLib_MakeWire`
//!   fails; here the degenerate profile stops the construction before
//!   `BRepFill_Evolved::Perform` (the wire would be empty otherwise).

mod perform;
mod profiles;
mod sections;

use occt_core::gp::GpAx3;
use occt_core::kernel::geomabs::JoinType;

use crate::brep_fill_evolved::BRepFillEvolved;
use crate::shape::{Edge, Face, TopoShape, Wire};

use super::shape_maps::ShapeValueMap;

/// `LocOpe_DPrism` (`hxx:38-84`).
#[derive(Clone)]
pub struct DPrism {
    /// `BRepFill_Evolved myDPrism` (`hxx:71`).
    my_dprism: BRepFillEvolved,
    /// `TopoDS_Shape myRes` (`hxx:72`).
    my_res: Option<TopoShape>,
    /// `TopoDS_Face mySpine` (`hxx:73`).
    my_spine: Face,
    /// `TopoDS_Wire myProfile` (`hxx:74`).
    my_profile: Option<Wire>,
    /// `TopoDS_Edge myProfile1` (`hxx:75`).
    my_profile1: Option<Edge>,
    /// `TopoDS_Edge myProfile2` (`hxx:76`).
    my_profile2: Option<Edge>,
    /// `TopoDS_Edge myProfile3` (`hxx:77`).
    my_profile3: Option<Edge>,
    /// `double myHeight` (`hxx:78`).
    my_height: f64,
    /// `TopoDS_Shape myFirstShape` (`hxx:79`).
    my_first_shape: Option<TopoShape>,
    /// `TopoDS_Shape myLastShape` (`hxx:80`).
    my_last_shape: Option<TopoShape>,
    /// `NCollection_DataMap<TopoDS_Shape, NCollection_List<TopoDS_Shape>>
    /// myMap` (`hxx:82`).
    my_map: ShapeValueMap<Vec<TopoShape>>,
}

impl DPrism {
    /// The state every constructor starts from: only `mySpine` is bound
    /// (`hxx:61-67` / `hxx:365-368` member-init lists).
    fn with_spine(spine: &Face) -> Self {
        Self {
            my_dprism: BRepFillEvolved::new(),
            my_res: None,
            my_spine: spine.clone(),
            my_profile: None,
            my_profile1: None,
            my_profile2: None,
            my_profile3: None,
            my_height: 0.0,
            my_first_shape: None,
            my_last_shape: None,
            my_map: ShapeValueMap::new(),
        }
    }

    /// `LocOpe_DPrism(Spine, Height1, Height2, Angle)` (`cxx:61-360`).
    pub fn with_two_heights(spine: &Face, height1: f64, height2: f64, angle: f64) -> Self {
        let mut this = Self::with_spine(spine);
        // `cxx:70`.
        this.my_height = height1 + height2;
        let Some(p) = profiles::dual_profile(spine, height1, height2, angle) else {
            return this;
        };
        this.my_profile1 = Some(p.edge1);
        this.my_profile2 = Some(p.edge2);
        this.my_profile3 = Some(p.edge3);
        this.my_profile = Some(p.wire);
        // `cxx:110-111`.
        this.perform_evolved();
        if this.my_dprism.is_done() {
            perform::perform_dual(&mut this);
        }
        this
    }

    /// `LocOpe_DPrism(Spine, Height, Angle)` (`cxx:365-552`).
    pub fn with_height(spine: &Face, height: f64, angle: f64) -> Self {
        let mut this = Self::with_spine(spine);
        // `cxx:369`.
        this.my_height = height;
        let Some(p) = profiles::single_profile(spine, height, angle) else {
            return this;
        };
        this.my_profile1 = Some(p.edge1);
        this.my_profile2 = Some(p.edge2);
        this.my_profile3 = Some(p.edge3);
        this.my_profile = Some(p.wire);
        // `cxx:389-390`.
        this.perform_evolved();
        if this.my_dprism.is_done() {
            perform::perform_single(&mut this);
        }
        this
    }

    /// `myDPrism.Perform(mySpine, myProfile, gp::XOY())` (`cxx:110`,
    /// `cxx:389`): the two-argument `Perform` keeps the `GeomAbs_Arc` join and
    /// `Solid = false` defaults (`BRepFill_Evolved.hxx:77-82`).
    fn perform_evolved(&mut self) {
        let Some(profile) = self.my_profile.clone() else {
            return;
        };
        // `BRepFill_Evolved::Perform` raises through `myError`; the port reports
        // it as `Err`, and `IsDone()` stays false exactly like the reference's
        // `myIsDone`.
        let _ = self
            .my_dprism
            .perform_face(&self.my_spine, &profile, &GpAx3::standard(), JoinType::Arc, false);
    }

    /// `IsDone()` (`cxx:556-559`): the flag of `BRepFill_Evolved`.
    pub fn is_done(&self) -> bool {
        self.my_dprism.is_done()
    }

    /// `Spine()` (`cxx:578-582`).
    pub fn spine(&self) -> &Face {
        &self.my_spine
    }

    /// `Profile()` (`cxx:586-589`); `None` is a null `myProfile`.
    pub fn profile(&self) -> Option<&Wire> {
        self.my_profile.as_ref()
    }

    /// `FirstShape()` (`cxx:593-596`).
    pub fn first_shape(&self) -> Option<&TopoShape> {
        self.my_first_shape.as_ref()
    }

    /// `LastShape()` (`cxx:600-603`).
    pub fn last_shape(&self) -> Option<&TopoShape> {
        self.my_last_shape.as_ref()
    }

    /// `Shape()` (`cxx:563-571`); `None` is the `StdFail_NotDone` raise.
    pub fn shape(&self) -> Option<&TopoShape> {
        if self.my_dprism.is_done() {
            self.my_res.as_ref()
        } else {
            None
        }
    }

    /// `Shapes(S)` (`cxx:605-618`): the rebuilt face of `S` when the
    /// profile-2 pass produced one, otherwise the descendant list of `S` for
    /// the middle profile edge. `None` is the `StdFail_NotDone` raise.
    pub fn shapes(&self, s: &TopoShape) -> Option<Vec<TopoShape>> {
        if !self.my_dprism.is_done() {
            return None;
        }
        if let Some(v) = self.my_map.find(s) {
            return Some(v.clone());
        }
        let profile2 = self.my_profile2.clone()?;
        Some(self.my_dprism.generated_shapes(s, &profile2.0))
    }

    /// `Curves(Scurves)` (`cxx:620-690`).
    pub fn curves(&self) -> Vec<std::sync::Arc<dyn occt_geom::curve::Curve>> {
        sections::curves(self)
    }

    /// `BarycCurve()` (`cxx:694-753`).
    pub fn baryc_curve(&self) -> Option<occt_geom::line::GeomLine> {
        sections::baryc_curve(self)
    }

    /// `myHeight` (`hxx:78`): `Height1 + Height2` for the two-heights ctor,
    /// `Height` for the single-height one.
    pub fn height(&self) -> f64 {
        self.my_height
    }

    /// `myProfile1` / `myProfile2` / `myProfile3` (`hxx:75-77`), in that order.
    pub fn profile_edges(&self) -> (Option<&Edge>, Option<&Edge>, Option<&Edge>) {
        (
            self.my_profile1.as_ref(),
            self.my_profile2.as_ref(),
            self.my_profile3.as_ref(),
        )
    }
}
